def fmt(x):
    return str(int(x)) if abs(x-round(x))<1e-10 else ('%.10g'%x)
def ans(x,prompt='Запиши ответ числом.'):
    s=str(x); return {'mode':'exact','prompt':prompt,'accepted':list(dict.fromkeys([s,s.replace('.',',')])), 'feedback':'Проверь, какую величину требуется найти, и сопоставь её с последним шагом.'}
def manual(prompt): return {'mode':'manual','prompt':prompt}
def st(title,prompt,explanation,reason,view='neutral',value=None):
    d=dict(title=title,prompt=prompt,explanation=explanation,reason=reason,view=view)
    if value is not None: d['input']=dict(prompt=prompt,accepted=[str(value),str(value).replace('.',',')],feedback='Сверь используемые данные с объяснением этого шага.')
    return d
def model(points,edges=None,views=None,labels=None,caption=None):
    names=list(points)
    pts={k:[*v,0] if len(v)==2 else v for k,v in points.items()}
    return dict(points=pts,edges=edges if edges is not None else [[names[i],names[(i+1)%len(names)]] for i in range(len(names))],labelNames=labels if labels is not None else names,planar=True,views={'neutral':{'label':'Исходная фигура'},**(views or {})},note=caption or 'Длины определяй по условию и свойствам фигуры, а не измерением экрана.')
def poly(points,**kw):return model(dict(zip('ABCDEFGHIJKLMNOPQRSTUVWXYZ',points)),**kw)
def add(sec,lev,num,part,page,title,text,goal,answer,hint,steps,m,caption='Отдельная модель задачи. Вспомогательные отрезки выделяются при переходе к шагам.'):
    lessons.append(dict(section=sec,level=lev,number=num,part=part,pages=[page],title=title,text=text,goal=goal,answer=answer,hint=hint,steps=steps,model=m,caption=caption))
def reg(n,side=None,angle=None):
    r=side/(2*math.sin(math.pi/n)) if side else 3
    pts={('_p'+str(i)):[r*math.cos(2*math.pi*i/n),r*math.sin(2*math.pi*i/n)] for i in range(n)}
    m=model(pts,labels=[])
    m['views']['fan']={'label':'Разбиение из одной вершины','segments':[['_p0','_p'+str(i)] for i in range(2,n-1)]}
    return m

