    m=model(pts,edges=[['A','B'],['B','C'],['C','D'],['D','A']],labels=['A','B','C','D'],views={'height':{'label':'Высота BH','segments':[['B','H']],'points':['H']}})
    add('2.2','A',2,part,39,'Высота трапеции по площади',f'Площадь трапеции равна {S}, сумма длин оснований равна {baseSum}. Найдите высоту трапеции.','Найди высоту трапеции.',ans(fmt(h),'Высота (число).'),'Используй формулу площади трапеции: S = (a + b)h/2.',[st('Средняя линия','Найди половину суммы оснований.',f'm = {baseSum}/2 = {baseSum//2}.','Средняя линия равна полусумме оснований.'),st('Выразим высоту','Как найти h из S = mh?',f'h = S/m = {S}/{baseSum//2}.','Деление обеих частей равенства на положительное m.','height'),st('Вычисление','Найди высоту.',f'h = {fmt(h)}. Проверка: {baseSum//2} · {fmt(h)} = {S}.','Подстановка результата в формулу площади.','height',fmt(h))],m,'Модель показывает одну трапецию с заданной суммой оснований и площадью; отдельные основания условием не определены.')
